std::vector<Point_2> hull;
if (points.size() < 3) return hull;

// Find the point with the lowest y-coordinate (or lowest x-coordinate if there is a tie)
Point_2 start = points[0];
for (const auto& p : points) {
    if (p.y() < start.y() || (p.y() == start.y() && p.x() < start.x())) {
        start = p;
    }
}

// Sort the points by polar angle with the start point
std::sort(points.begin(), points.end(), [&start](const Point_2& a, const Point_2& b) {
    return (a - start).cross(b - start) > 0;
});

hull.push_back(points[0]);
hull.push_back(points[1]);

for (size_t i = 2; i < points.size(); ++i) {
    while (hull.size() > 1 && (points[i] - hull[hull.size() - 2]).cross(hull[hull.size() - 1] - hull[hull.size() - 2]) <= 0) {
        hull.pop_back();
    }
    hull.push_back(points[i]);
}

return hull;

